/// <summary>
/// Extension of the BarcodeSetup table.
/// </summary>
[ExtensionOf(tableStr(BarcodeSetup))]
internal final class AVARUMBarcodeSetupDbt_Extension
{
}

Method.Source:
/// <summary>
/// Validates the given barcode string.
/// </summary>
/// <param name="barCodeString">The barcode string to validate.</param>
/// <param name="_suppressMessages">Indicates whether to suppress validation messages.Optional. Default: true</param>
/// <returns>True if the barcode is valid, otherwise false.</returns>
public boolean validateBarcode_AVA(BarCodeString barCodeString, boolean _suppressMessages = true)
{
    int lastInfoLine;
    boolean isValid;

    // Get the current line number in the infolog.
    lastInfoLine = Global::infologLine();

    try
    {
        // Validate the barcode string.
        isValid = this.validateBarcode(barCodeString);
    }
    catch (Exception::Error)
    {
        // If an error occurs, the barcode is not valid.
        isValid = false;
    }

    // Clear infolog messages if suppression is requested.
    if (_suppressMessages)
    {
        infolog.clear(lastInfoLine);
    }

    // Return the validation result.
    return isValid;
}
